  &DefaultButton;




function dir$dmmst(p){
  this.constructor(p);
}
dir$dmmst.prototype = new DirEvent();

dir$dmmst.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  switch (cF){
    default:
      break;
  }
}

function getTax(o) {
  var p = document._dir;
  var tax = p.valForm('ma_so_thue');
  if (tax.length != 10 && tax.length != 13) {
    $.showToast('Thông tin mã số thuế không đúng.');
    return;
  }

  $.invoke('GetTax', { taxCode: tax }, this, 30000
    , function (result) {
      if (result) {
        var obj = JSON.parse(result);
        p.valForm('ten_kh', obj.Name, true);
        p.valForm('dia_chi', obj.Address, true);
		p.valForm('nguoi_lh', obj.Contact, true);
		p.valForm('dien_thoai', obj.Telephone, true);

      }
    }, function (event) {} );

}

dir$dmmst.prototype.afterInit = function(renderType){
  var p = this._dir,g = p.grid()

  dir$dmmstDisabledMasterField(p, g);
  var p = this._dir;
  document._dir = p;
}

function dir$dmmstDisabledMasterField(p, g){
	if(p.valForm('ma_so_thue').trim() != '')
  {
    p.setDisabled('ma_so_thue', true);
  }
  else
  {
    p.setDisabled('ma_so_thue', false);
  }
}







	.control-label.ma_so_thue, .control-label.ten_kh, .control-label.dien_thoai
	{		
		color: #499b98;;
	}









